class Solution {
    public boolean checkValidString(String s) {
        int low = 0;
        int high = 0;

        for (char c : s.toCharArray()) {
            if (c == '(') {
                low++;
                high++;
            } else if (c == ')') {
                low--;
                high--;
            } else {
                low--;
                high++;
            }
            if (high < 0) {
                return false;
            }
            low = Math.max(low, 0);
        }

        return low == 0;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public boolean checkValidString(String s) {
        Deque<Integer> openStack = new ArrayDeque<>();
        Deque<Integer> starStack = new ArrayDeque<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                openStack.push(i);
            } else if (c == '*') {
                starStack.push(i);
            } else if (!openStack.isEmpty()) {
                openStack.pop();
            } else if (!starStack.isEmpty()) {
                starStack.pop();
            } else {
                return false;
            }
        }

        while (!openStack.isEmpty() && !starStack.isEmpty()) {
            if (openStack.pop() > starStack.pop()) {
                return false;
            }
        }
        return openStack.isEmpty();
    }
}

class Solution {
    public boolean checkValidString(String s) {
        Boolean[][] memo = new Boolean[s.length() + 1][s.length() + 1];
        return dfs(s, 0, 0, memo);
    }

    private boolean dfs(String s, int index, int balance, Boolean[][] memo) {
        if (balance < 0) {
            return false;
        }
        if (balance > s.length() - index) {
            return false;
        }
        if (index == s.length()) {
            return balance == 0;
        }
        if (memo[index][balance] != null) {
            return memo[index][balance];
        }

        char c = s.charAt(index);
        boolean valid;
        if (c == '(') {
            valid = dfs(s, index + 1, balance + 1, memo);
        } else if (c == ')') {
            valid = dfs(s, index + 1, balance - 1, memo);
        } else {
            valid = dfs(s, index + 1, balance + 1, memo)
                    || dfs(s, index + 1, balance, memo)
                    || dfs(s, index + 1, balance - 1, memo);
        }
        memo[index][balance] = valid;
        return valid;
    }
}

class Solution {
    public boolean checkValidString(String s) {
        int n = s.length();
        boolean[] reachable = new boolean[n + 1];
        reachable[0] = true;

        for (char c : s.toCharArray()) {
            boolean[] next = new boolean[n + 1];
            for (int balance = 0; balance <= n; balance++) {
                if (!reachable[balance]) {
                    continue;
                }
                if (c == '(') {
                    if (balance + 1 <= n) {
                        next[balance + 1] = true;
                    }
                } else if (c == ')') {
                    if (balance > 0) {
                        next[balance - 1] = true;
                    }
                } else {
                    next[balance] = true;
                    if (balance + 1 <= n) {
                        next[balance + 1] = true;
                    }
                    if (balance > 0) {
                        next[balance - 1] = true;
                    }
                }
            }
            reachable = next;
        }

        return reachable[0];
    }
}

class Solution {
    public boolean checkValidString(String s) {
        int balance = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == ')') {
                balance--;
            } else {
                balance++;
            }
            if (balance < 0) {
                return false;
            }
        }

        balance = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == '(') {
                balance--;
            } else {
                balance++;
            }
            if (balance < 0) {
                return false;
            }
        }
        return true;
    }
}
